-- 포캐스트 최종 개발용 더미데이터입니다.
-- 상품 이천칠백삼십 개와 옵션 일만 구백구십 개를 프론트 원본에 맞췄습니다.
-- 주문과 매출 및 리뷰는 이천이십삼 년 십일월 이십일부터 이천이십육 년 십일월 십구일까지 분산합니다.
-- 기존 초기화 파일로 테이블을 만든 빈 개발 데이터베이스에서 실행하세요. 기존 데이터는 삭제하지 않습니다.
-- 매뉴얼 제오장의 날짜 구조ㆍ외래키 순서ㆍ집계ㆍ번호 증가 규칙을 적용합니다.
-- 기본 회원과 관리자는 각각 한 명씩 생성하며 비밀번호는 암호화해 저장합니다.
-- 나머지 가상 회원은 비밀번호가 없어 로그인용으로 사용할 수 없습니다.
-- 원료ㆍ생애주기ㆍ재질은 원본 자료가 없어 비워 두었습니다. 원가는 미제공으로 영을 저장합니다.
-- 이익 예측에는 실제 원가 자료가 필요하며 감성 학습에는 검수된 리뷰 본문과 정답 자료가 필요합니다.
-- 소진일ㆍ반품ㆍ교환ㆍ행동 기록ㆍ쿠폰ㆍ포인트는 확정된 테이블과 통신 규격이 필요해 생성하지 않습니다.
-- 팀에서는 상품 및 옵션 식별자 연결ㆍ공통 코드ㆍ매출일ㆍ배송비ㆍ환불 차감 기준을 결정해야 합니다.
-- 인공지능 추천 결과 저장 구조와 기존 추천 테이블의 차이도 팀에서 통일해야 합니다.
-- 합성 리뷰는 화면 확인용입니다. 과거 가격 이력이 없어 현재 가격을 관측 기간 전체에 사용합니다.
-- 프론트의 가상 평점과 판매량을 가져오지 않고 생성된 이력으로 집계합니다.
-- 과거 시점 학습에는 당시까지의 집계만 사용하고 합성 데이터의 성능을 실제 서비스 성능으로 해석하지 마세요.
-- 일반 쿼리 편집기에서 전체 실행하세요. 실패한 트랜잭션이 있다면 먼저 롤백하세요.
SET client_encoding TO 'UTF8';
BEGIN;
DO $$
BEGIN
 IF EXISTS(SELECT 1 FROM members) OR EXISTS(SELECT 1 FROM products)
    OR EXISTS(SELECT 1 FROM categories) OR EXISTS(SELECT 1 FROM orders) THEN
  RAISE EXCEPTION '빈 개발 DB에서만 실행하세요. 기존 데이터는 삭제하지 않습니다.';
 END IF;
END $$;
SELECT setseed(0.20261110);
-- 2026-11-19 기준 최근 3년, 양끝 포함. 재현성을 위해 관측일 고정.
CREATE TEMP TABLE demo_period ON COMMIT DROP AS
SELECT DATE '2023-11-20' start_date, DATE '2026-11-19' end_date;

SELECT i,'demo_'||i,'테스트회원'||i,'demo'||i||'@example.com',
 CASE WHEN i=1 THEN 'ADMIN' ELSE 'USER' END,'ACTIVE',true,true,true,false,
 DATE '2023-11-19',DATE '2023-11-19'
FROM generate_series(1,2000) i;
-- 첫 회원을 관리자로, 두 번째 회원을 기본 테스트 회원으로 설정합니다.
-- 요청한 공통 개발용 비밀번호를 백엔드와 동일한 방식으로 암호화했습니다.
UPDATE members SET user_id='admin',name='기본 관리자',email='admin@example.com',
 password_hash='$2a$10$OUH/D6QUL0dDNU5YO5NSgur2TBdcNetWZWZApSflqrT5PmU1U53A.',role='ADMIN' WHERE id=1;
UPDATE members SET user_id='test001',name='기본 테스트 회원',email='test001@example.com',
 password_hash='$2a$10$OUH/D6QUL0dDNU5YO5NSgur2TBdcNetWZWZApSflqrT5PmU1U53A.',role='USER' WHERE id=2;
SELECT id,'테스트 배송지',name,'010-0000-0000','00000','테스트시 테스트로 1','가상 주소',true FROM members;
UPDATE products SET created_at=DATE '2023-11-19',updated_at=DATE '2023-11-19';
UPDATE product_images SET is_main=true,created_at=DATE '2023-11-19',updated_at=DATE '2023-11-19';
UPDATE product_variants SET created_at=DATE '2023-11-19',updated_at=DATE '2023-11-19';
SELECT id,id,'테스트펫'||id,CASE WHEN id%2=0 THEN 'CAT' ELSE 'DOG' END,
 (DATE '2026-11-19'-make_interval(months=>6+(id%150)::int))::date,'믹스',CASE WHEN id%2=0 THEN 4.5 ELSE 7.2 END,
 CASE WHEN id%7=0 THEN 'CHICKEN' ELSE NULL END,DATE '2026-11-19',DATE '2026-11-19' FROM members WHERE id>1;

-- 회원별 종/가격 선호, 활동 기간. 시뮬레이션용 임시 테이블로만 사용.
CREATE TEMP TABLE demo_profiles ON COMMIT DROP AS
SELECT id,CASE WHEN id%2=0 THEN 'CAT' ELSE 'DOG' END species,
 id%3 tier,0.2+random()*0.8 activity FROM members WHERE id>1;

DO $$
DECLARE day_index int; n int; j int; k int; mid bigint; pid bigint; vid bigint;
 oid bigint:=0; iid bigint:=0; qty int; price_value numeric; subtotal numeric;
 st text; ordered_at timestamp; item_count int; expected numeric;
 first_day date; last_day date; total_days int;
BEGIN
 SELECT start_date,end_date INTO first_day,last_day FROM demo_period;
 total_days:=last_day-first_day+1;
 FOR day_index IN 0..total_days-1 LOOP
  ordered_at := first_day+make_interval(days=>day_index)+INTERVAL '12 hours';
  expected := (20+12*day_index/total_days::numeric)*
    (ARRAY[0.86,1.18,1.10,1.05,1.02,1.00,0.82])[1+extract(dow FROM ordered_at)::int]*
    (ARRAY[0.92,0.95,1.08,1.02,1.05,0.98,1.12,1.14,1.00,1.03,1.22,1.06])[extract(month FROM ordered_at)::int]*
    CASE WHEN extract(day FROM ordered_at) BETWEEN 24 AND 27 THEN 1.2 ELSE 1 END;
  n:=greatest(1,round(expected*(0.7+random()*0.6))::int);
  FOR j IN 1..n LOOP
   oid:=oid+1;
   -- 기간 후반에 회원이 모두 탈락하는 기존 생애기간 조건을 제거.
   SELECT id INTO mid FROM demo_profiles
    ORDER BY -ln(greatest(random(),0.000001))/activity LIMIT 1;
   IF random()<0.08 THEN mid:=NULL; END IF;
   ordered_at := first_day+make_interval(days=>day_index)+INTERVAL '8 hours'+random()*INTERVAL '12 hours';
   st:=CASE WHEN random()<0.045 THEN 'CANCELLED' WHEN day_index<total_days-10 THEN 'DELIVERED'
      WHEN day_index<total_days-6 THEN 'SHIPPING' WHEN day_index<total_days-3 THEN 'PREPARING' ELSE 'PAID' END;
   VALUES(oid,mid,'DEMO-'||lpad(oid::text,12,'0'),st,0,0,'가상 수령인','010-0000-0000',coalesce('demo'||mid,'guest'||oid)||'@example.com','00000','테스트시 테스트로 1','가상 주소',ordered_at);
   item_count:=1+floor(random()*3)::int;
   FOR k IN 1..item_count LOOP
    SELECT p.id INTO pid FROM products p
    WHERE (mid IS NULL OR EXISTS(SELECT 1 FROM product_pet_types pt WHERE pt.product_id=p.id AND pt.pet_type=(SELECT species FROM demo_profiles WHERE id=mid)))
    AND NOT EXISTS(SELECT 1 FROM order_items oi JOIN product_variants pv ON pv.id=oi.product_variant_id WHERE oi.order_id=oid AND pv.product_id=p.id)
    ORDER BY random() DESC LIMIT 1;
    SELECT id INTO vid FROM product_variants WHERE product_id=pid ORDER BY random() LIMIT 1;
    SELECT price INTO price_value FROM product_variants WHERE id=vid;
    qty:=1+floor(random()*2)::int; iid:=iid+1;
    SELECT iid,oid,vid,p.name,v.option_label,qty,price_value,qty*price_value
    FROM products p JOIN product_variants v ON v.product_id=p.id WHERE v.id=vid;
   END LOOP;
   SELECT sum(total_price) INTO subtotal FROM order_items WHERE order_id=oid;
   UPDATE orders SET total_amount=subtotal,shipping_fee=CASE WHEN subtotal>=50000 THEN 0 ELSE 3000 END,
    final_amount=subtotal+CASE WHEN subtotal>=50000 THEN 0 ELSE 3000 END WHERE id=oid;
  END LOOP;
 END LOOP;
END $$;
SELECT id,id,(ARRAY['CARD','BANK','EASY_PAY'])[1+id%3],'DEMO_ONLY','DEMO-NOT-A-PG-KEY-'||id,'DEMO-IDEMPOTENCY-'||id,final_amount,
 CASE WHEN status='CANCELLED' THEN 'CANCELLED' ELSE 'PAID' END,created_at+INTERVAL '1 minute',created_at FROM orders;
SELECT id,'DEMO-REFUND-'||id,amount,'개발용 취소 사례','COMPLETED',created_at+INTERVAL '1 hour',created_at+INTERVAL '2 hours' FROM payments WHERE status='CANCELLED';
SELECT id,status,created_at+INTERVAL '1 day',CASE WHEN status='DELIVERED' THEN created_at+INTERVAL '3 days' END FROM orders WHERE status IN ('SHIPPING','DELIVERED');
SELECT o.member_id,v.product_id,oi.id,
 CASE WHEN r<0.08 THEN 1 WHEN r<0.12 THEN 2 WHEN r<0.22 THEN 3 WHEN r<0.45 THEN 4 ELSE 5 END,
 (ARRAY['잘 먹지만 포장은 조금 아쉬워요.','기대보다 무난하고 좀 더 써봐야겠어요.','배송은 늦었지만 상품은 만족합니다.','기호성이 좋아서 다시 구매했어요.','우리 아이에게는 맞지 않는 것 같아요.','사용하기 편하고 관리도 쉬워요.'])[1+floor(random()*6)::int],
 o.created_at+delay,o.created_at+delay
FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN product_variants v ON v.id=oi.product_variant_id
CROSS JOIN LATERAL (SELECT random()+oi.id*0 AS r) noise
CROSS JOIN LATERAL (SELECT make_interval(days=>4+floor(random()*11+oi.id*0)::int) AS delay) review_delay
WHERE o.status='DELIVERED' AND o.member_id IS NOT NULL
 AND o.created_at+delay<(SELECT end_date+1 FROM demo_period) AND random()<0.32;
-- 리뷰 본문은 평점 정답 라벨이 아님. 감성 AI 학습에는 별도 라벨링/데이터 분할 필요.
SELECT m.id,p.id FROM members m CROSS JOIN generate_series(1,3) s JOIN (SELECT id,row_number() OVER(ORDER BY id)-1 rn FROM products) p ON p.rn=(m.id*7+s*13)%2730 WHERE m.id>1;
SELECT i,i+1,'GENERAL','[테스트] 배송 문의 '||i,'개발용 문의입니다.',i%3=0 FROM generate_series(1,100) i;
-- 문의/답변 역시 생성 실행일에 몰리지 않게 배치. 답변은 문의 이후.
UPDATE qnas SET created_at=DATE '2023-11-20'+(id*11%1096)::int*INTERVAL '1 day',
 updated_at=DATE '2023-11-20'+(id*11%1096)::int*INTERVAL '1 day';
UPDATE qna_answers a SET created_at=q.created_at+INTERVAL '2 hours',updated_at=q.created_at+INTERVAL '2 hours' FROM qnas q WHERE q.id=a.qna_id;
-- 집계값은 실제 생성된 상세 레코드에서 계산.
UPDATE product_variants v SET sales_count=coalesce((SELECT sum(oi.quantity) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_variant_id=v.id AND o.status<>'CANCELLED'),0);
UPDATE products p SET sales_count=(SELECT sum(v.sales_count) FROM product_variants v WHERE v.product_id=p.id),
 wish_count=(SELECT count(*) FROM wishlists w WHERE w.product_id=p.id),
 review_count=(SELECT count(*) FROM product_reviews r WHERE r.product_id=p.id),
 rating_sum=coalesce((SELECT sum(r.rating) FROM product_reviews r WHERE r.product_id=p.id),0);
-- 명시적 ID 적재 이후 identity 시퀀스를 실제 최댓값으로 전진.
DO $$ DECLARE t record; sequence_name text; maximum bigint;
BEGIN
 FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='id' AND is_identity='YES' LOOP
  sequence_name:=pg_get_serial_sequence(format('public.%I',t.table_name),'id');
  EXECUTE format('SELECT max(id) FROM public.%I',t.table_name) INTO maximum;
  IF maximum IS NOT NULL THEN PERFORM setval(sequence_name,maximum,true); END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM orders o WHERE o.total_amount<>(SELECT sum(total_price) FROM order_items WHERE order_id=o.id) OR o.final_amount<>o.total_amount-o.discount_amount+o.shipping_fee) THEN
  RAISE EXCEPTION '주문 금액 검증 실패';
 END IF;
END $$;
COMMIT;
SELECT 'members' AS entity,count(*) FROM members UNION ALL SELECT 'products',count(*) FROM products UNION ALL SELECT 'orders',count(*) FROM orders UNION ALL SELECT 'reviews',count(*) FROM product_reviews;

-- 적재 후 실행하는 읽기 전용 검수. 판매 완료/환불 날짜 기준은 팀 합의 필요.
-- 빈 월도 0건으로 표시. 첫 달/마지막 달은 부분 월이므로 일평균을 비교한다.
WITH months AS (
 SELECT generate_series(DATE '2023-11-01',DATE '2026-11-01',INTERVAL '1 month')::date AS report_month
), orders_month AS (
 SELECT date_trunc('month',created_at)::date AS report_month,count(*) order_count,
 sum(final_amount) FILTER(WHERE status<>'CANCELLED') order_sales
 FROM orders WHERE order_number LIKE 'DEMO-%' GROUP BY 1
), reviews_month AS (
 SELECT date_trunc('month',r.created_at)::date AS report_month,count(*) review_count
 FROM product_reviews r JOIN order_items oi ON oi.id=r.order_item_id
 JOIN orders o ON o.id=oi.order_id WHERE o.order_number LIKE 'DEMO-%' GROUP BY 1
), refunds_month AS (
 SELECT date_trunc('month',r.completed_at)::date AS report_month,sum(refund_amount) refunded
 FROM refunds r JOIN payments p ON p.id=r.payment_id
 JOIN orders o ON o.id=p.order_id WHERE o.order_number LIKE 'DEMO-%' GROUP BY 1
)
SELECT m.report_month,
 least((m.report_month+INTERVAL '1 month')::date,DATE '2026-11-20')-greatest(m.report_month,DATE '2023-11-20') covered_days,
 coalesce(o.order_count,0) orders,coalesce(o.order_sales,0) non_cancelled_order_sales,
 coalesce(r.review_count,0) reviews,coalesce(f.refunded,0) refunded,
 round(coalesce(o.order_count,0)::numeric/nullif(least((m.report_month+INTERVAL '1 month')::date,DATE '2026-11-20')-greatest(m.report_month,DATE '2023-11-20'),0),2) orders_per_day
FROM months m LEFT JOIN orders_month o USING(report_month)
LEFT JOIN reviews_month r USING(report_month) LEFT JOIN refunds_month f USING(report_month)
ORDER BY report_month;

-- 다음 결과는 모두 0이어야 한다.
SELECT 'orders_outside_period' check_name,count(*) violations FROM orders
 WHERE order_number LIKE 'DEMO-%' AND (created_at<DATE '2023-11-20' OR created_at>=DATE '2026-11-20')
UNION ALL
SELECT 'review_before_delivery_or_after_end',count(*) FROM product_reviews r
 JOIN order_items oi ON oi.id=r.order_item_id JOIN orders o ON o.id=oi.order_id
 LEFT JOIN shipments s ON s.order_id=o.id WHERE o.order_number LIKE 'DEMO-%'
 AND (s.delivered_at IS NULL OR r.created_at<s.delivered_at OR r.created_at>=DATE '2026-11-20')
UNION ALL
SELECT 'payment_before_order_or_after_end',count(*) FROM payments p JOIN orders o ON o.id=p.order_id
 WHERE o.order_number LIKE 'DEMO-%' AND (p.paid_at<o.created_at OR p.paid_at>=DATE '2026-11-20');

-- 전체 매출의 10% 이상이 단일 월에 몰리면 확인 필요(합성 데이터 검수용 기준).
WITH monthly AS (
 SELECT date_trunc('month',created_at) AS report_month,sum(final_amount) revenue FROM orders
 WHERE order_number LIKE 'DEMO-%' AND status<>'CANCELLED' GROUP BY 1
)
SELECT report_month,revenue,round(100*revenue/nullif(sum(revenue) OVER(),0),2) share_percent,
 revenue>sum(revenue) OVER()*0.10 AS concentration_warning FROM monthly ORDER BY report_month;
